<script setup lang="ts">
import { ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import { ArrowRight, BookOpen, CheckCircle2, GraduationCap, LockKeyhole, Sparkles, Video } from "lucide-vue-next";
import { useAuthStore } from "@/stores/auth";
const auth = useAuthStore();
const router = useRouter();
const route = useRoute();
const username = ref("");
const password = ref("");
const error = ref("");
const busy = ref(false);
async function onSubmit() {
  error.value = ""; busy.value = true;
  try { await auth.login(username.value, password.value); router.push(typeof route.query.redirect === "string" ? route.query.redirect : "/"); }
  catch (e) { error.value = e instanceof Error ? e.message : "登录失败"; }
  finally { busy.value = false; }
}
</script>
